import React, { useState, useEffect, useCallback } from 'react';
import './App.css';

const BACKEND_URL = 'http://localhost:5000/api';

export default function App() {
  // ============ STATE ============
  const [isGhostMode, setIsGhostMode] = useState(true);
  const [calcInput, setCalcInput] = useState('');
  const [calcDisplay, setCalcDisplay] = useState('0');
  const [calcExpression, setCalcExpression] = useState('');
  const [category, setCategory] = useState('Mental Health');
  const [storyText, setStoryText] = useState('');
  const [globalStories, setGlobalStories] = useState([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [replyText, setReplyText] = useState('');
  const [replyingTo, setReplyingTo] = useState(null);
  const [showReplies, setShowReplies] = useState({});
  const [replies, setReplies] = useState({});
  const [sosStatus, setSosStatus] = useState('');

  // ============ OFFLINE SYNC ============
  const syncOfflineStories = useCallback(async () => {
    try {
      const offlineData = localStorage.getItem('offlineStories');
      if (!offlineData) return;
      const queue = JSON.parse(offlineData);
      if (queue.length === 0) return;
      for (const story of queue) {
        await fetch(`${BACKEND_URL}/story/save`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(story),
        });
      }
      localStorage.removeItem('offlineStories');
      fetchStories();
      alert('Your offline posts have been successfully synced!');
    } catch (err) {
      console.log('Sync failed.');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ============ FETCH STORIES ============
  const fetchStories = useCallback(async () => {
    try {
      const response = await fetch(`${BACKEND_URL}/story/get`);
      const data = await response.json();
      if (data.success) {
        setGlobalStories(data.stories);
        setIsOffline(false);
      }
    } catch (err) {
      setIsOffline(true);
    }
  }, []);

  // ============ ONLINE/OFFLINE LISTENERS ============
  useEffect(() => {
    fetchStories();
    const goOnline = () => {
      setIsOffline(false);
      syncOfflineStories();
    };
    const goOffline = () => setIsOffline(true);
    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);
    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, [fetchStories, syncOfflineStories]);

  // ============ POST STORY ============
  const handlePostStory = async (e) => {
    e.preventDefault();
    if (!storyText.trim()) return;
    const newStory = {
      id: Date.now(),
      story: storyText,
      category: category,
      timestamp: new Date().toISOString(),
      location: 'Anonymous User',
      replies: 0
    };
    if (isOffline) {
      const existingQueue = localStorage.getItem('offlineStories');
      const queue = existingQueue ? JSON.parse(existingQueue) : [];
      queue.push(newStory);
      localStorage.setItem('offlineStories', JSON.stringify(queue));
      alert('Offline mode! Your message will send when reconnected.');
      setStoryText('');
      setGlobalStories(prev => [newStory, ...prev]);
    } else {
      try {
        const response = await fetch(`${BACKEND_URL}/story/save`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newStory)
        });
        const data = await response.json();
        if (data.success) {
          setStoryText('');
          fetchStories();
        }
      } catch (err) {
        setIsOffline(true);
        const existingQueue = localStorage.getItem('offlineStories');
        const queue = existingQueue ? JSON.parse(existingQueue) : [];
        queue.push(newStory);
        localStorage.setItem('offlineStories', JSON.stringify(queue));
        setStoryText('');
        setGlobalStories(prev => [newStory, ...prev]);
      }
    }
  };

  // ============ REPLY FUNCTIONS (NESTED) ============
  const addReply = (storyId, parentId, text) => {
    const newReply = {
      id: Date.now(),
      text: text,
      parentId: parentId || null,
      timestamp: new Date().toISOString(),
      children: []
    };

    setReplies(prev => {
      const storyReplies = prev[storyId] || [];

      if (!parentId) {
        return {
          ...prev,
          [storyId]: [newReply, ...storyReplies]
        };
      }

      const addChild = (list) => {
        return list.map(reply => {
          if (reply.id === parentId) {
            return {
              ...reply,
              children: [newReply, ...(reply.children || [])]
            };
          }
          if (reply.children) {
            return {
              ...reply,
              children: addChild(reply.children)
            };
          }
          return reply;
        });
      };

      return {
        ...prev,
        [storyId]: addChild(storyReplies)
      };
    });

    setGlobalStories(prev => prev.map(story =>
      story.id === storyId
        ? { ...story, replies: (story.replies || 0) + 1 }
        : story
    ));

    try {
      fetch(`${BACKEND_URL}/story/reply`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          storyId: storyId,
          reply: text,
          parentId: parentId || null
        })
      });
    } catch (err) {
      console.log('Reply saved locally');
    }
  };

  const handleReplySubmit = (storyId) => {
    if (!replyText.trim()) return;
    addReply(storyId, replyingTo === storyId ? null : replyingTo, replyText);
    setReplyText('');
    setReplyingTo(null);
  };

  // ============ RENDER NESTED REPLIES ============
  const renderReplies = (storyId, replyList, depth = 0) => {
    if (!replyList || replyList.length === 0) return null;

    return replyList.map((reply) => (
      <div key={reply.id} style={{ marginLeft: `${depth * 20}px` }}>
        <div style={styles.replyCard}>
          <div style={styles.replyHeader}>
            <span style={styles.replyAnonymous}>💬 Anonymous supporter</span>
            <span style={styles.replyTime}>{formatMessageTime(reply.timestamp)}</span>
          </div>
          <p style={styles.replyText}>{reply.text}</p>
          <button
            style={styles.nestedReplyButton}
            onClick={() => setReplyingTo(replyingTo === reply.id ? null : reply.id)}
          >
            ↳ Reply
          </button>
          {replyingTo === reply.id && (
            <div style={styles.replyInputContainer}>
              <input
                type="text"
                style={styles.replyInput}
                placeholder="Write a reply..."
                value={replyText}
                onChange={(e) => setReplyText(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleReplySubmit(storyId)}
                autoFocus
              />
              <button style={styles.sendReplyButton} onClick={() => handleReplySubmit(storyId)}>Send</button>
            </div>
          )}
          {reply.children && renderReplies(storyId, reply.children, depth + 1)}
        </div>
      </div>
    ));
  };

  // ============ CALCULATOR FUNCTIONS ============
  const handleCalcPress = (val) => {
    // AC Button - Clear everything
    if (val === 'AC') {
      setCalcInput('');
      setCalcDisplay('0');
      setCalcExpression('');
      return;
    }

    // SECRET CODE CHECK - MUST BE FIRST!
    if (val === '=') {
      if (calcInput === '9999') {
        setIsGhostMode(false);
        setCalcInput('');
        setCalcDisplay('0');
        setCalcExpression('');
        return;
      }
      try {
        // eslint-disable-next-line no-eval
        const result = eval(calcInput);
        setCalcDisplay(result.toString());
        setCalcExpression(calcInput + ' = ' + result);
        setCalcInput(result.toString());
      } catch {
        setCalcDisplay('Error');
        setCalcInput('');
      }
      return;
    }

    // Scientific functions
    const fnMap = {
      'sin(': 'Math.sin(',
      'cos(': 'Math.cos(',
      'tan(': 'Math.tan(',
      'log(': 'Math.log10(',
      '√(': 'Math.sqrt('
    };
    if (fnMap[val]) {
      setCalcInput(prev => prev + fnMap[val]);
      setCalcDisplay(prev => (prev === '0' ? val : prev + val));
      return;
    }
    if (val === 'π') {
      setCalcInput(prev => prev + Math.PI.toString());
      setCalcDisplay(prev => (prev === '0' ? 'π' : prev + 'π'));
      return;
    }
    if (val === 'e') {
      setCalcInput(prev => prev + Math.E.toString());
      setCalcDisplay(prev => (prev === '0' ? 'e' : prev + 'e'));
      return;
    }

    // Regular input
    setCalcInput(prev => prev + val);
    setCalcDisplay(prev => (prev === '0' ? val : prev + val));
  };

  // ============ SOS FUNCTION ============
  const triggerSOS = async () => {
    setSosStatus("🚨 SOS TRIGGERED! Getting your location...");

    if (!navigator.geolocation) {
      alert('❌ Your browser does not support GPS. Please call 100, 102, or 1930 directly.');
      setSosStatus("❌ Browser doesn't support GPS.");
      return;
    }

    const options = {
      enableHighAccuracy: true,
      timeout: 15000,
      maximumAge: 0
    };

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        const locationLink = `https://maps.google.com/?q=${lat},${lng}`;

        const payload = {
          location: { lat: lat, lng: lng },
          contacts: [
            { name: '🚓 POLICE', phone: '100' },
            { name: '🚑 AMBULANCE', phone: '102' },
            { name: '🕵️ CBI', phone: '1930' }
          ]
        };

        try {
          await fetch(`${BACKEND_URL}/location/alert`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });

          alert(`🚨 EMERGENCY SOS SENT!\n\n📍 Your location: ${lat}, ${lng}\n🗺️ ${locationLink}\n\n📞 Police: 100 | Ambulance: 102 | CBI: 1930\n\nHelp is on the way.`);
          setSosStatus(`✅ SOS Sent! Location found.`);

        } catch (err) {
          alert(`⚠️ SOS SAVED! Location: ${lat}, ${lng}\n\nWill send when internet returns.`);
          setSosStatus(`⚠️ SOS saved offline.`);
        }
      },
      (error) => {
        let errorMsg = "";
        switch (error.code) {
          case error.PERMISSION_DENIED:
            errorMsg = "❌ Location permission denied. Please allow location in browser settings and try again.";
            break;
          case error.POSITION_UNAVAILABLE:
            errorMsg = "❌ GPS signal not found. Please go outside or near a window and try again.";
            break;
          case error.TIMEOUT:
            errorMsg = "❌ GPS is taking too long. Please check your location settings and try again.";
            break;
          default:
            errorMsg = "❌ Could not get your location. Please call 100, 102, or 1930 directly.";
        }
        alert(errorMsg);
        setSosStatus("❌ Could not get location. Please check GPS.");
      },
      options
    );
  };

  // ============ UTILITY FUNCTIONS ============
  const activateGhostMode = () => {
    setStoryText('');
    setIsGhostMode(true);
  };

  const toggleReplies = (storyId) => {
    setShowReplies(prev => ({
      ...prev,
      [storyId]: !prev[storyId]
    }));
  };

  const formatMessageTime = (timestamp) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  const getCategoryStyle = (category) => {
    if (category === 'Mental Health') return { backgroundColor: '#8b5cf6', padding: '2px 8px', borderRadius: '12px', fontSize: '10px', color: '#fff' };
    if (category === 'Abuse Support') return { backgroundColor: '#ef4444', padding: '2px 8px', borderRadius: '12px', fontSize: '10px', color: '#fff' };
    return { backgroundColor: '#f59e0b', padding: '2px 8px', borderRadius: '12px', fontSize: '10px', color: '#fff' };
  };

  // ============ RENDER: GHOST CALCULATOR ============
  if (isGhostMode) {
    return (
      <div style={styles.calcContainer}>
        <div style={styles.calcScreen}>
          <div style={styles.calcExpression}>{calcExpression}</div>
          <div style={styles.calcDisplay}>{calcDisplay}</div>
        </div>
        <div style={styles.calcGrid}>
          {/* Scientific Row 1 */}
          <div style={styles.calcRow}>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('sin(')}>sin</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('cos(')}>cos</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('tan(')}>tan</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('log(')}>log</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('√(')}>√</button>
          </div>
          {/* Scientific Row 2 */}
          <div style={styles.calcRow}>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('π')}>π</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('e')}>e</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress('(')}>(</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn }} onClick={() => handleCalcPress(')')}>)</button>
            <button style={{ ...styles.calcBtn, ...styles.calcFnBtn, ...styles.calcAcBtn }} onClick={() => handleCalcPress('AC')}>AC</button>
          </div>
          {/* Number Pad */}
          {[
            ['7', '8', '9', '/'],
            ['4', '5', '6', '*'],
            ['1', '2', '3', '-'],
            ['0', '.', '=', '+']
          ].map((row, rIdx) => (
            <div key={rIdx} style={styles.calcRow}>
              {row.map((char) => (
                <button
                  key={char}
                  style={char === '=' ? { ...styles.calcBtn, ...styles.calcEqualsBtn } : styles.calcBtn}
                  onClick={() => handleCalcPress(char)}
                >
                  {char}
                </button>
              ))}
            </div>
          ))}
        </div>
        <div style={styles.calcHint}>🔒 Enter 9999= to unlock</div>
      </div>
    );
  }

  // ============ RENDER: MAIN APP ============
  return (
    <div style={styles.appContainer}>
      <div style={styles.ghostBar} onClick={activateGhostMode}>
        <span>🔒 System Framework Secure • Click to Minimize</span>
      </div>
      {isOffline && (
        <div style={styles.offlineBanner}>
          ⚠️ Offline Mode - Messages will sync when online
        </div>
      )}
      <main style={styles.mainLayout}>
        <h1 style={styles.mainHeading}>The Anonymous Global Sanctuary</h1>
        <section style={styles.panel}>
          <h3 style={{ marginTop: 0, color: '#f3f4f6' }}>Release Your Story Completely Anonymously</h3>
          <div style={styles.categoryRow}>
            {['Mental Health', 'Abuse Support', 'Bullying'].map((cat) => (
              <button
                key={cat}
                style={{ ...styles.catBtn, ...(category === cat ? styles.catBtnActive : {}) }}
                onClick={() => setCategory(cat)}
              >
                {cat}
              </button>
            ))}
          </div>
          <form onSubmit={handlePostStory}>
            <textarea
              style={styles.textArea}
              placeholder="What burdens are you holding today? No identities tracked here..."
              value={storyText}
              onChange={(e) => setStoryText(e.target.value)}
              rows="3"
            />
            <button type="submit" style={styles.submitBtn}>
              📢 Publish Story
            </button>
          </form>
        </section>
        <section style={{ marginTop: '30px' }}>
          <h2 style={{ color: '#9ca3af', fontSize: '1.25rem' }}>Shared Journeys Around the World</h2>
          {globalStories.length === 0 ? (
            <p style={{ color: '#6b7280' }}>No stories yet. Be the first to share!</p>
          ) : (
            globalStories.map((item) => (
              <div key={item.id} style={styles.storyCard}>
                <div style={styles.storyHeader}>
                  <span style={getCategoryStyle(item.category)}>{item.category}</span>
                  <small style={{ color: '#64748b', fontSize: '10px' }}>{formatMessageTime(item.timestamp)}</small>
                </div>
                <p style={styles.storyText}>{item.story}</p>
                <div style={styles.storyActions}>
                  <button style={styles.replyButton} onClick={() => setReplyingTo(replyingTo === item.id ? null : item.id)}>
                    💬 Reply ({replies[item.id]?.length || item.replies || 0})
                  </button>
                  <button style={styles.viewRepliesButton} onClick={() => toggleReplies(item.id)}>
                    {showReplies[item.id] ? '▲ Hide replies' : '▼ View replies'}
                  </button>
                </div>
                {/* Reply Input (top-level, only when replying directly to the story) */}
                {replyingTo === item.id && (
                  <div style={styles.replyInputContainer}>
                    <input
                      type="text"
                      style={styles.replyInput}
                      placeholder="Write a reply..."
                      value={replyText}
                      onChange={(e) => setReplyText(e.target.value)}
                      onKeyPress={(e) => e.key === 'Enter' && handleReplySubmit(item.id)}
                      autoFocus
                    />
                    <button style={styles.sendReplyButton} onClick={() => handleReplySubmit(item.id)}>Send</button>
                  </div>
                )}
                {/* Nested Replies Display */}
                {showReplies[item.id] && replies[item.id] && replies[item.id].length > 0 && (
                  <div style={styles.repliesSection}>
                    {renderReplies(item.id, replies[item.id])}
                  </div>
                )}
              </div>
            ))
          )}
        </section>
      </main>
      <footer style={styles.sosFooter} onClick={triggerSOS}>
        🚨 TRIGGER SATELLITE EMERGENCY SOS
      </footer>
    </div>
  );
}

